public String sortString(String s) {
    if (s == null || s.length() <= 1) {
        return s;
    }

    Map<Character, Integer> charCount = new HashMap<>();
    for (char c : s.toCharArray()) {
        charCount.put(c, charCount.getOrDefault(c, 0) + 1);
    }

    PriorityQueue<Character> minHeap = new PriorityQueue<>((a, b) -> charCount.get(a) - charCount.get(b));
    PriorityQueue<Character> maxHeap = new PriorityQueue<>((a, b) -> charCount.get(b) - charCount.get(a));

    for (char c : s.toCharArray()) {
        if (charCount.get(c) > 1) {
            minHeap.offer(c);
        } else {
            minHeap.offer(c);
            maxHeap.offer(c);
        }
    }

    StringBuilder result = new StringBuilder();
    boolean isAscending = true;

    while (!minHeap.isEmpty()) {
        if (isAscending) {
            while (!minHeap.isEmpty() && charCount.containsKey(minHeap.peek())) {
                result.append(minHeap.poll());
                charCount.put(minHeap.peek(), charCount.get(minHeap.peek()) - 1);
            }
        } else {
            while (!maxHeap.isEmpty() && charCount.containsKey(maxHeap.peek())) {
                result.append(maxHeap.poll());
                charCount.put(maxHeap.peek(), charCount.get(maxHeap.peek()) - 1);
            }
        }
        isAscending = !isAscending;
    }

    return result.toString();
}

