public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0 || s.length() < k) return false;

    int needed = (int) Math.pow(2, k);
    boolean[] seen = new boolean[needed];

    int right = 0;
    while (right < s.length()) {
        int substringStart = right - k + 1;
        if (substringStart >= 0 && !seen[s.substring(substringStart, right + 1).hashCode()]) {
            seen[s.substring(substringStart, right + 1).hashCode()] = true;
        } else {
            return false;
        }
        right++;
    }

    return true;
}

