public static double calculateProbability(int n) {
    if (n <= 1) {
        return 1.0; // Base case: The probability is always 1 when there's only one passenger or no passengers.
    }
    double[][] dp = new double[n][n]; // 2D DP array to store results for subproblems.
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (j == i) {
                dp[i][j] = 1; // Probability of the last passenger sitting in their own seat.
            } else {
                dp[i][j] = 0; // Probability of the last passenger not sitting in their own seat.
            }
        }
    }
    for (int len = 3; len <= n; len++) {
        for (int i = 0; i <= n - len; i++) {
            int j = i + len - 1;
            for (int k = i; k < j; k++) {
                dp[i][j] += dp[i][k] * dp[k + 1][j];
            }
        }
    }
    return dp[0][n - 1] / (double)(n - 1); // Calculate the probability and return it as a double.
}

public static int singleNumber(int[] nums) {
    int[] count = new int[32]; // To count the bits of each element

    for (int num : nums) {
        for (int j = 0; j < 32; j++) {
            count[j] += (num >> j) & 1; // Count bits
        }
    }

    int result = 0;
    for (int j = 0; j < 32; j++) {
        result |= (count[j] % 3) << j; // Reconstruct the result
    }

    return result;
}

