public static int squarePermutations(int[] A) {
    int n = A.length;
    int count = 0;

    for (int i = 0; i < n - 1; i++) {
        int sum = A[i] + A[i + 1];
        if (isPerfectSquare(sum)) {
            count += squarePermutationsDerivative(A, i, new HashSet<>());
        }
    }

    return count;
}

private static boolean isPerfectSquare(int x) {
    if (x < 0) return false;
    int s = (int) Math.sqrt(x);
    return s * s == x;
}

private static int squarePermutationsDerivative(int[] A, int start, Set<Integer> used) {
    int n = A.length;
    if (start >= n - 1) {
        return 1;
    }

    int count = 0;
    for (int i = start + 1; i < n; i++) {
        if (!used.contains(A[i])) {
            used.add(A[i]);
            count += squarePermutationsDerivative(A, i, used);
            used.remove(A[i]);
        }
    }

    return count;
}

public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    if (n == 0) {
        return 0;
    }

    int[] stack = new int[n];
    int top = -1;
    int maxArea = 0;

    for (int i = 0; i < n; i++) {
        while (top != -1 && heights[i] < heights[stack[top]]) {
            int height = heights[stack[top]];
            stack[top--];
            int width = top == -1 ? i : i - stack[top - 1] - 1;
            maxArea = Math.max(maxArea, height * width);
        }
        stack[++top] = i;
    }

    while (top != -1) {
        int height = heights[stack[top]];
        stack[top--];
        int width = top == -1 ? n : n - stack[top - 1] - 1;
        maxArea = Math.max(maxArea, height * width);
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int index = 0;

    int i = 0, j = 0;
    int direction = 1; // 1 for right, -1 for left

    while (index < rows * cols) {
        result[index++] = mat[i][j];
        if (direction == 1) {
            if (j + 1 < cols) j++; // Go right if possible
            else i++; // Move down if not possible
        } else {
            if (i + 1 < rows) i++; // Go down if possible
            else j++; // Move right if not possible
        }
        direction *= -1; // Change direction
    }

    return result;
}

public static int findSmallestInteger(int n) {
        String numStr = String.valueOf(n);
        int[] digits = new int[numStr.length()];
        for (int i = 0; i < numStr.length(); i++) {
            digits[i] = numStr.charAt(i) - '0';
        }

        Arrays.sort(digits);
        // Find the index of the smallest digit that is greater than the first digit
        for (int i =(digits.length - 1); i > 0; i--) {
            if (digits[i - 1] < digits[i]) {
                // Swap the smallest digit and the first digit
                int temp = digits[i - 1];
                digits[i - 1] = digits[i];
                digits[i] = temp;
                // Sort the rest of the digits in ascending order
                Arrays.sort(digits, i);
                break;
            }
        }

        // Convert the sorted digits back to an integer
        StringBuilder smallestStr = new StringBuilder();
        for (int digit : digits) {
            smallestStr.append(digit);
        }
        int smallestInteger = smallestStr.length() > 0 ? Integer.parseInt(smallestStr.toString()) : -1;

        return smallestInteger;
    }

