public static int minPerfectSquareSum(int n) {
    if (n <= 0) { // Invalid input: must be a positive integer
        throw new IllegalArgumentException("Input must be a positive integer");
    }

    int[] dp = new int[n + 1];

    // Initialize dp array with the maximum value
    for (int i = 1; i <= n; i++) {
        dp[i] = i;
    }

    // Fill the dp array
    for (int i = 1; i * i <= n; i++) {
        for (int j = i * i; j <= n; j++) {
            dp[j] = Math.min(dp[j], 1 + dp[j - i * i]);
        }
    }

    return dp[n];
}

